HASHES = {'app_bch_flow/templates/app_bch_flow/landing/index.html': '200f59341ea646063d22f6caba781dbbc4bd8ef3523869e8b54071fd50b67cdb', 'app_bch_flow/static/app_bch_flow/css/pages/landing-enterprise-v2.css': '9eaad8ad034b15c4fa234e71f6549caba714bb249aedf1f041cd58acfb7979d0', 'app_bch_flow/static/app_bch_flow/js/landing-enterprise-v2.js': '9ffffebdc428a2957874512e5aaac3391218142185393dab402b027748594475', 'app_bch_flow/static/app_bch_flow/images/brand/landing-logo.png': '935adf5b0ca3fdc882f0703820e07506cfb5c21b50f5427a17bd24e33626bda2'}
TEMPLATE = 'app_bch_flow/templates/app_bch_flow/landing/index.html'
CSS = 'app_bch_flow/static/app_bch_flow/css/pages/landing-enterprise-v2.css'
JS = 'app_bch_flow/static/app_bch_flow/js/landing-enterprise-v2.js'
LOGO = 'app_bch_flow/static/app_bch_flow/images/brand/landing-logo.png'
ORDER = (CSS, JS, LOGO, TEMPLATE)

def sha(data):
    return hashlib.sha256(data).hexdigest()

def abort(msg):
    raise SystemExit('ABORTADO: ' + msg)

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', default='/home/farcry/Documents/bch-flow')
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--dry-run', action='store_true')
    mode.add_argument('--apply', action='store_true')
    args = parser.parse_args()
    root = Path(args.root).expanduser().resolve()
    if not (root / 'manage.py').is_file() or not (root / 'app_bch_flow/templates/app_bch_flow/base.html').is_file():
        abort('raiz Django ou base.html nao encontrados: ' + str(root))
    for rel in (
        'app_bch_flow/static/app_bch_flow/videos/bch-flow-demo.mp4',
        'app_bch_flow/static/app_bch_flow/images/bch-flow-demo.jpg',
    ):
        if not (root / rel).is_file():
            abort('asset existente necessario ausente: ' + rel)
    decoded = {}
    for rel, encoded in PAYLOAD.items():
        data = zlib.decompress(base64.b85decode(encoded.encode('ascii')))
        if sha(data) != HASHES[rel]:
            abort('SHA256 divergente: ' + rel)
        decoded[rel] = data
    html = decoded[TEMPLATE].decode('utf-8')
    required = (
        "{% extends 'app_bch_flow/base.html' %}",
        'landing-enterprise-v2.css',
        'landing-enterprise-v2.js',
        'landing-logo.png',
        'bch-flow-demo.mp4',
        'hackathon_presentation_url',
        'hackathon_token_address',
        'jury_configured',
        'bch_flow:register',
        'bch_flow:login',
    )
    for needle in required:
        if needle not in html:
            abort('componente exigido ausente: ' + needle)
    if html.count('bch_flow:jury_enter') != 2 or html.count('{% csrf_token %}') != 2:
        abort('formularios dos jurados nao preservados')
    if 'landing.css' in html or 'landing-media.css' in html or 'landing-video.js' in html or 'landing-experience.js' in html:
        abort('referencia a CSS/JS legado encontrada no novo template')
    try:
        from django.template import Engine
        Engine(debug=False).from_string(html)
        print('Template Django: sintaxe OK')
    except ImportError:
        print('Django nao encontrado neste interpretador: valide com manage.py check no venv')
    except Exception as exc:
        abort('template Django invalido: ' + str(exc))
    target = root / TEMPLATE
    if not target.is_file() or target.is_symlink():
        abort('template original nao encontrado ou symlink')
    before = target.read_bytes()
    if b'bch_flow:jury_enter' not in before:
        abort('template existente inesperado; nao substituir')
    if before == decoded[TEMPLATE]:
        abort('V2 ja aplicada; nenhuma alteracao necessaria')
    for rel in ORDER:
        dest = root / rel
        if dest.is_symlink() or not dest.parent.is_dir():
            abort('diretorio de destino invalido ou symlink: ' + rel)
        if rel in (CSS, JS) and dest.exists():
            abort('asset V2 ja existe: ' + rel + '; revise antes de substituir')
        if rel == LOGO and dest.exists() and sha(dest.read_bytes()) != HASHES[rel]:
            abort('logo landing-logo.png difere da fornecida; abortando para preservar alteracoes')
    print('BCH FLOW LANDING ENTERPRISE V2')
    print('Raiz:', root)
    print('HTML novo com CSS/JS V2 exclusivos; nao importa CSS/JS legado da landing')
    print('Acesso jurados, CSRF, CashTokens, GitHub, video e rotas preservados')
    print('Logo oficial fornecida pelo usuario')
    for rel in ORDER:
        print(' ', rel, sha(decoded[rel]))
    print('Template atual:', sha(before))
    if args.dry_run:
        print('DRY-RUN OK: nenhum arquivo modificado')
        return
    backup_dir = root / '.bch_flow_landing_backups' / ('enterprise_v2_' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
    staged = {}
    committed = []
    existed = {}
    try:
        backup_dir.mkdir(parents=True, exist_ok=False)
        for rel in ORDER:
            dest = root / rel
            existed[rel] = dest.exists()
            if dest.exists():
                backup = backup_dir / rel
                backup.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(dest, backup)
                if sha(backup.read_bytes()) != sha(dest.read_bytes()):
                    raise RuntimeError('falha de backup: ' + rel)
        for rel in ORDER:
            dest = root / rel
            fd, temp = tempfile.mkstemp(prefix='.bch_flow_v2_', dir=str(dest.parent))
            with os.fdopen(fd, 'wb') as stream:
                stream.write(decoded[rel])
                stream.flush()
                os.fsync(stream.fileno())
            os.chmod(temp, stat.S_IMODE(dest.stat().st_mode) if dest.exists() else 0o644)
            staged[rel] = temp
        if target.read_bytes() != before:
            raise RuntimeError('template alterado durante a instalacao')
        for rel in ORDER:
            dest = root / rel
            if rel in (CSS, JS) and dest.exists():
                raise RuntimeError('arquivo V2 criado simultaneamente: ' + rel)
            if rel == LOGO and dest.exists() and sha(dest.read_bytes()) != HASHES[rel]:
                raise RuntimeError('logo alterada durante a instalacao')
            os.replace(staged.pop(rel), dest)
            committed.append(rel)
            if sha(dest.read_bytes()) != HASHES[rel]:
                raise RuntimeError('checksum final invalido: ' + rel)
    except Exception as exc:
        for rel in reversed(committed):
            dest = root / rel
            if existed[rel]:
                shutil.copy2(backup_dir / rel, dest)
            elif dest.exists():
                dest.unlink()
        abort(str(exc) + ' | rollback dos arquivos ja gravados executado')
    finally:
        for temp in staged.values():
            if os.path.exists(temp):
                os.unlink(temp)
    print('INSTALADO OK')
    print('Backup:', backup_dir)
    print('O py.py original, backend, settings, banco e pagamentos nao foram alterados')
    print('Valide: cd ' + str(root) + ' && python3 manage.py check')
    print('Restaure o template do backup se desejar reverter; os assets V2 podem ser removidos depois')

if __name__ == '__main__':
    main()
